@'
from pathlib import Path

selftest = Path('project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py')
text = selftest.read_text(encoding='utf-8')
old = "import tempfile\nimport unittest\nfrom pathlib import Path\n\nmock = unittest.mock\n"
new = "import tempfile\nimport unittest\nimport unittest.mock as mock\nfrom pathlib import Path\n"
if text.count(old) != 1:
    raise SystemExit(f'expected one evaluator mock-import block, found {text.count(old)}')
